const ClientsComponent={render:(content,layout,colorMode,pStyle,lang)=>{const items=String(content||'').split(/[\n,]/).map(s=>s.trim()).filter(Boolean);if(!items.length)return'';const t=SectionUtils.theme(colorMode,pStyle);const title=lang==='th'?'ลูกค้า / หน่วยงานที่ร่วมงาน':'Clients / Partners';return SectionUtils.wrap(SectionUtils.title(title,t)+`<div class="client-logo-grid">${items.map(x=>`<span>${x}</span>`).join('')}</div>`,'clients-section')}};
